from collections.abc import Callable
from typing import Any
import httpx


@pytest.fixture
def mock_http(
    monkeypatch: pytest.MonkeyPatch,
) -> Callable[[Callable[[httpx.Request], httpx.Response]], None]:
    original_client = httpx.Client

    def install(handler: Callable[[httpx.Request], httpx.Response]) -> None:
        def client(**kwargs: Any) -> httpx.Client:
            return original_client(transport=httpx.MockTransport(handler), **kwargs)

        monkeypatch.setattr(geo_host_preflight.httpx, "Client", client)

    return install


@pytest.mark.parametrize("url", ["http://example.com/", "file:///etc/passwd", "ftp://example.com/"])
def test_get_rejects_non_https_before_network(url: str, mock_http: Any) -> None:
    def unexpected(_: httpx.Request) -> httpx.Response:
        pytest.fail("invalid URL reached the transport")

    mock_http(unexpected)
    with pytest.raises(ValueError, match="require https"):
        geo_host_preflight._get(url, 1)


def test_get_rejects_redirect_downgrade_before_network(mock_http: Any) -> None:
    seen: list[str] = []

    def respond(request: httpx.Request) -> httpx.Response:
        seen.append(str(request.url))
        return httpx.Response(302, headers={"Location": "http://example.com/insecure"})

    mock_http(respond)
    with pytest.raises(ValueError, match="require https"):
        geo_host_preflight._get("https://example.com/", 1)
    assert seen == ["https://example.com/"]


def test_get_retains_redirect_identity_error_body_and_repeated_headers(mock_http: Any) -> None:
    responses: list[httpx.Response] = []

    def respond(request: httpx.Request) -> httpx.Response:
        if request.url.path == "/":
            response = httpx.Response(302, headers={"Location": "/missing"})
        else:
            response = httpx.Response(
                404,
                headers=[
                    ("Content-Type", "text/html; charset=utf-8"),
                    ("X-Robots-Tag", "noindex"),
                    ("X-Robots-Tag", "nofollow"),
                ],
                content=b"missing page",
            )
        responses.append(response)
        return response

    mock_http(respond)
    assert geo_host_preflight._get("https://example.com/", 1) == (
        404,
        "https://example.com/missing",
        "text/html",
        "noindex, nofollow",
        b"missing page",
    )
    assert all(response.is_closed for response in responses)


def test_get_closes_oversized_response(mock_http: Any, monkeypatch: pytest.MonkeyPatch) -> None:
    response = httpx.Response(200, content=b"too large")
    monkeypatch.setattr(geo_host_preflight, "_MAX_RESPONSE_BYTES", 4)
    mock_http(lambda _: response)
    with pytest.raises(ValueError, match="exceeds 4 bytes"):
        geo_host_preflight._get("https://example.com/", 1)
    assert response.is_closed

"""Progress reminders must preserve unknown state and cannot authorize a merge."""

from __future__ import annotations

import json
import os
import subprocess
from pathlib import Path

import pytest

HOOK = Path(__file__).resolve().parents[2] / ".claude/hooks/check-progress.sh"


@pytest.mark.parametrize(
    "history,fetch,branch,ahead,expected",
    [
        (0, 0, 0, 0, ""),
        (1, 0, 0, 0, "커밋 조회 실패"),
        (0, 1, 0, 0, "원격 조회 실패"),
        (0, 0, 1, 0, "브랜치 조회 실패"),
        (0, 0, 0, 3, "커밋 수는 병합 근거가 아닙니다"),
    ],
)
def test_reminder_is_truthful_and_advisory(
    tmp_path: Path, history: int, fetch: int, branch: int, ahead: int, expected: str
) -> None:
    shell = r"""
git() {
  case "$*" in
    'rev-list --count --since='*) printf '0\n'; return "$HISTORY_EXIT" ;;
    'fetch origin --quiet') return "$FETCH_EXIT" ;;
    'rev-list --count origin/main..origin/develop') printf '%s\n' "$AHEAD"; return "$BRANCH_EXIT" ;;
    *) return 99 ;;
  esac
}
source "$1"
"""
    result = subprocess.run(  # noqa: S603 -- inert Git stubs, fixed hook under test
        ["/bin/bash", "-c", shell, "progress-hook-test", str(HOOK)],
        cwd=tmp_path,
        env={
            **os.environ,
            "HISTORY_EXIT": str(history),
            "FETCH_EXIT": str(fetch),
            "BRANCH_EXIT": str(branch),
            "AHEAD": str(ahead),
        },
        text=True,
        capture_output=True,
        check=False,
        timeout=10,
    )
    assert result.returncode == 0, result.stderr
    report = json.loads(result.stdout)
    assert report["continue"] is True
    if expected:
        assert expected in report["message"]
        assert "merge를 진행하세요" not in report["message"]
    else:
        assert report == {"continue": True}
